import { afterEach, describe, expect, it, vi } from "vitest";

import { authorizeAgentRequest, handleSessionRequest } from "./auth";

const DEMO_SECRET = "[REDACTED]";

describe("demo session authorization", () => {
  afterEach(() => vi.useRealTimers());

  it("allows local development without a shared secret", async () => {
    await expect(
      authorizeAgentRequest(new Request("http://127.0.0.1/agents/rlm/demo"), undefined),
    ).resolves.toBe(null);
  });

  it("fails closed when a deployed demo has no strong secret", async () => {
    for (const secret of [undefined, "too-short"]) {
      const response = await authorizeAgentRequest(
        new Request("https://rlm.example.com/agents/rlm/demo"),
        secret,
      );

      expect(response?.status).toBe(503);
      await expect(response?.json()).resolves.toMatchObject({
        error: expect.stringContaining("DEMO_TOKEN"),
      });
    }
  });

  it("exchanges the configured token for a signed HttpOnly session cookie", async () => {
    const response = await openSession();
    const cookie = response.headers.get("set-cookie") ?? "";

    expect(response.status).toBe(204);
    expect(response.headers.get("cache-control")).toBe("no-store");
    expect(cookie).toContain("__Host-rlm-session=");
    expect(cookie).not.toContain(DEMO_SECRET);
    expect(cookie).toContain("HttpOnly");
    expect(cookie).toContain("Secure");
    expect(cookie).toContain("SameSite=Strict");
  });

  it("requires a valid signed session cookie for deployed agent routes", async () => {
    await expect(
      authorizeAgentRequest(new Request("https://rlm.example.com/agents/rlm/demo"), DEMO_SECRET),
    ).resolves.toMatchObject({ status: 401 });
    await expect(
      authorizeAgentRequest(
        new Request("https://rlm.example.com/agents/rlm/demo", {
          headers: { cookie: `__Host-rlm-session=${DEMO_SECRET}` },
        }),
        DEMO_SECRET,
      ),
    ).resolves.toMatchObject({ status: 401 });

    const cookie = await sessionCookie();
    await expect(
      authorizeAgentRequest(
        new Request("https://rlm.example.com/agents/rlm/demo", {
          headers: { cookie },
        }),
        DEMO_SECRET,
      ),
    ).resolves.toBe(null);
  });

  it("rejects an expired signed session cookie", async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-08-21T12:00:00Z"));
    const cookie = await sessionCookie();
    vi.advanceTimersByTime(8 * 60 * 60 * 1000 + 1);

    await expect(
      authorizeAgentRequest(
        new Request("https://rlm.example.com/agents/rlm/demo", {
          headers: { cookie },
        }),
        DEMO_SECRET,
      ),
    ).resolves.toMatchObject({ status: 401 });
  });

  it("does not accept the shared token in a URL", async () => {
    await expect(
      authorizeAgentRequest(
        new Request(`https://rlm.example.com/agents/rlm/demo?token=[REDACTED]}`),
        DEMO_SECRET,
      ),
    ).resolves.toMatchObject({ status: 401 });
  });
});

async function openSession(): Promise<Response> {
  return handleSessionRequest(
    new Request("https://rlm.example.com/api/session", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ token: DEMO_SECRET }),
    }),
    DEMO_SECRET,
  );
}

async function sessionCookie(): Promise<string> {
  const response = await openSession();
  return (response.headers.get("set-cookie") ?? "").split(";", 1)[0] ?? "";
}

# `@cloudflare/computer`

> [!IMPORTANT]
> The `@cloudflare/computer` package should be considered suitable for
> production use. The package contains work-in-progress and experimental
> components such as the `ContainerBackend`. These should be considered
> unsuitable for production use. See the [status reference](../packages/computer/README.md#status) for more details.
>
> The specification in this directory is forward-looking — read it for
> intent, not as description of the code today.

The `@cloudflare/computer` package provides an out of the box virtual filesystem for use in any Durable Object — it's persistent and backed by SQLite. It's primarily designed for agents that need small, portable filesystems and tools to work with.

![Architecture overview](./assets/arch.png)

It provides:

 - A fs API for working with files and directories compatible with Worker bindings.
 - Read-only mounts for pre-filling the workspace tree from an R2 bucket or from files shipped with the Worker.
 - Durability over DO restarts for all file operations.
 - Pluggable execution backends selected through `workspace.runtime`: a Cloudflare Container shell, a just-bash Dynamic Worker, or an isolated ECMAScript-module Dynamic Worker.
 - Isolated JavaScript with structured input/results, durable relative imports, configured libraries, durable `node:fs/promises`, host modules such as `ws:git`, `ws:container`, `ws:assets` and `ws:tools`, and managed execution records.
 - Workspace constructable without a backend, for filesystem-only use cases.
 - Out-of-the-box agent tools for the AI SDK (`createAITools()` in `@cloudflare/computer/tools/ai-sdk`), pi (`createPiTools()` in `@cloudflare/computer/tools/pi-ai`), and TanStack AI (`createTanStackTools()` in `@cloudflare/computer/tools/tanstack-ai`).

It comes with the following limitations:

 - ~10GB maximum (it shares storage with the DO).
 - The container-side filesystem is held in memory, so very large trees aren't a fit. Aim for agent-scale workspaces, not full monorepos.
 - Container access goes through FUSE, so heavy IO workloads (large `node_modules` installs, big tarball extractions) take a measurable performance hit compared to a native filesystem.

## Installation

Install the package into your Worker/Agent project:

```sh
npm install @cloudflare/computer
```

The package ships several entrypoints:

| Entrypoint | Purpose |
| --- | --- |
| `@cloudflare/computer` | The Workspace wrapper, first-class `workspace.runtime`, stub types, the R2 and Worker bundle mounts, and proxy classes. |
| `@cloudflare/computer/backends/container` | `ContainerBackend` and `withWorkspaceContainer`, for a container the durable object schedules (`scheduling_policy: "durable_object"`). Same sync plumbing; the launch names the image and the instance size. |
| `@cloudflare/computer/backends/container-legacy` | Deprecated; use `@cloudflare/computer/backends/container`. `LegacyContainerBackend` and `withLegacyWorkspaceContainer`, for a container the platform schedules and sizes from the containers block. |
| `@cloudflare/computer/backends/worker-shell` | `WorkerShellBackend` and the bundled just-bash command runtime. |
| `@cloudflare/computer/backends/worker-javascript` | `WorkerJavaScriptBackend`, configured libraries, durable relative imports, `node:fs/promises`, and host modules. |
| `@cloudflare/computer/git` | Opt-in isomorphic-git glue for working with checkouts inside the workspace. Bundled lazily, with `pako` replaced by Workers `node:zlib`, and kept out of the default `@cloudflare/computer` graph. |
| `@cloudflare/computer/artifacts` | `createArtifact`, an optionally session-scoped wrapper over the Cloudflare Artifacts Workers binding, plus its argv CLI. |
| `@cloudflare/computer/modules/container` | `createContainerModule()` for `ws:container`: run container commands from isolate JavaScript. |
| `@cloudflare/computer/modules/git` | `createGitModule()` for `ws:git`: confined Git from isolate JavaScript. |
| `@cloudflare/computer/modules/artifacts` | `createArtifactsModule()` for `ws:artifacts`: Artifacts and git tokens from isolate JavaScript. |
| `@cloudflare/computer/modules/assets` | `createAssetsModule()` for `ws:assets`: publish a Workspace file from isolate JavaScript. |
| `@cloudflare/computer/modules/tools` | `createToolBindings()` for `ws:tools`: an agent's own tools, callable from isolate JavaScript. |
| `@cloudflare/computer/tools` | AI SDK tools for agents: read, write, edit, ls, optional exec, and optional publish. |
| `@cloudflare/computer/tools/core` | `defineExec()`: the `exec` tool's description, schema, and executor, with no agent library. |
| `@cloudflare/computer/tools/ai-sdk` | `createAITools()`: the AI SDK tool set for a Workspace. |
| `@cloudflare/computer/tools/pi-ai` | `createPiTools()`: the same tool set for pi, as declarations plus a function that runs a tool call. |
| `@cloudflare/computer/tools/tanstack-ai` | `createTanStackTools()`: the same tool set for TanStack AI, as the list `chat({ tools })` takes. |

A consumer that only uses the container backend never imports the
worker subpath, so the just-bash payload tree-shakes away.

Wire types shared with the in-container service live in the sibling package `@cloudflare/computer-rpc` (subpaths `./server`, `./client`, `./driver`).

### Sandbox container image

The container needs the `computerd` daemon alongside a FUSE runtime. The
simplest pattern, used by [`examples/container/Dockerfile`](../examples/container/Dockerfile),
copies the prebuilt binary out of the public GHCR image and into a thin
Debian base:

```dockerfile
FROM ghcr.io/cloudflare/computer-computerd-linux-x64:0.6.0 AS computerd

FROM debian:stable-slim

RUN apt-get update \
 && apt-get install -y --no-install-recommends \
      fuse3 libfuse2t64 ca-certificates \
 && rm -rf /var/lib/apt/lists/*

COPY --from=computerd /usr/local/bin/computerd /usr/local/bin/computerd

ENV PORT=8080
ENV MOUNT_POINT=/workspace
ENV FUSE_MOUNT=auto
EXPOSE 8080

ENTRYPOINT ["/usr/local/bin/computerd"]
```

To build the binary from source instead, run `npm run build:bin
--workspace @cloudflare/computerd`, which emits
`artifacts/computerd/computerd-linux-x64`, then `COPY` that into the
image.

`computerd`'s own default port is `45678`; the Cloudflare container backend pins the in-image listener to `8080`, which is what [`examples/container`](../examples/container) uses. See [07. Injected Service](./07_injected_service.md) for the env vars (`PORT`, `MOUNT_POINT`, `FUSE_MOUNT`, `EXEC_LOG_MAX_BYTES`) and the reverse-dial boot sequence.

## Example

```ts
import { Workspace } from "@cloudflare/computer";
import {
  ContainerBackend,
  withWorkspaceContainer,
} from "@cloudflare/computer/backends/container";
import { DurableObject } from "cloudflare:workers";

export class Agent extends withWorkspaceContainer(class extends DurableObject<Env> {}) {
  readonly backend = new ContainerBackend({
    container: () => this,
    workspace: { binding: "Agent", id: this.ctx.id.toString() },
    name: "app",
    instance: "standard-2",
  });

  readonly workspace = new Workspace({
    storage: this.ctx.storage, // Durable Object storage → VFS lives here
    backends: [this.backend],
  });

  async initialize() {
    await this.workspace.ready();
    await this.workspace.fs.mkdir("/workspace", { recursive: true });
  }

  override fetch(request: Request): Promise<Response> {
    return this.backend.handleFetch(request);
  }
}
```

Once you have a `workspace` on your Durable Object, the `fs` and `runtime` surfaces feel a lot like Node's `fs/promises` plus routed command/module execution — everything is async, paths are absolute, and operations are durable across DO restarts.

Create and write files:

```ts
// Write a string (utf8 by default for strings).
await this.workspace.fs.writeFile("/workspace/notes/todo.md", "- [ ] ship it\n");

// Write binary content.
await this.workspace.fs.writeFile("/workspace/data/blob.bin", new Uint8Array([1, 2, 3]));

// Stream a large upload straight to disk.
await this.workspace.fs.writeFile("/workspace/uploads/big.csv", request.body!);
```

Read files back:

```ts
// As a string.
const todo = await this.workspace.fs.readFile("/workspace/notes/todo.md", "utf8");

// As a stream — handy for piping into a Response.
const stream = await this.workspace.fs.readFile("/workspace/uploads/big.csv");
return new Response(stream);
```

Create and walk directories:

```ts
await this.workspace.fs.mkdir("/workspace/notes/daily", { recursive: true });

for (const entry of await this.workspace.fs.readdir("/workspace/notes")) {
  console.log(entry.isDirectory ? `d ${entry.name}` : `f ${entry.name}`);
}
```

Remove files and directories:

```ts
await this.workspace.fs.rm("/workspace/notes/todo.md");
await this.workspace.fs.rm("/workspace/notes/daily", { recursive: true });
```

Search across the tree:

```ts
const hits = await this.workspace.fs.grep("TODO", "/workspace", { ignoreCase: true });
for (const hit of hits) {
  console.log(`${hit.path}:${hit.line}: ${hit.text}`);
}
```

Run a shell command in the sandbox — the same filesystem is mounted there, so writes from `fs` are immediately visible to `exec` and vice versa:

```ts
const run = await this.workspace.runtime.exec("ls -la /workspace", { encoding: "utf8" });
const { stdout, exitCode } = await run.result();
console.log(stdout, exitCode);
```

`exec` returns a `ReadableStream` of events as well as the buffered `result()`. That makes it straightforward to forward live output to the browser as a Server-Sent Events stream — just transform each event into an SSE frame:

```ts
// Inside a fetch handler on your Agent.
async fetch(request: Request) {
  const run = await this.workspace.runtime.exec("npm test", { encoding: "utf8" });

  const sse = run.pipeThrough(
    new TransformStream<
      | { id: string; seq: number; name: "stdout" | "stderr"; value: string }
      | { id: string; seq: number; name: "exit"; value: number },
      Uint8Array
    >({
      transform(event, controller) {
        // SSE frame: `event: <name>\ndata: <json>\n\n`
        const frame = `event: ${event.name}\ndata: ${JSON.stringify(event.value)}\n\n`;
        controller.enqueue(new TextEncoder().encode(frame));
      },
    }),
  );

  return new Response(sse, {
    headers: {
      "content-type":  "text/event-stream",
      "cache-control": "no-cache",
      "connection":    "keep-alive",
    },
  });
}
```

On the client:

```ts
const events = new EventSource("/agent/run");
events.addEventListener("stdout", (e) => console.log(JSON.parse(e.data)));
events.addEventListener("stderr", (e) => console.warn(JSON.parse(e.data)));
events.addEventListener("exit",   (e) => { console.log("exit", JSON.parse(e.data)); events.close(); });
```

## Documentation

This package is documented as a set of focused topics. Start with the overview
above, then dive into the area you're working on.

The status column says whether the API a document describes is stable or
experimental. Reference documents describe the code or its performance
rather than an API.

| Document | Status | Topic |
| --- | --- | --- |
| [01. VFS](./01_vfs.md) | Stable | Layout of the workspace tree, reserved paths, and mount points. |
| [02. Sync Protocol](./02_sync_protocol.md) | Experimental | How the DO-backed VFS synchronises with the sandbox container. |
| [03. Filesystem Schema](./03_filesystem_schema.md) | Stable | SQLite schema backing the virtual filesystem. |
| [04. Filesystem Interface](./04_filesystem_interface.md) | Stable | `Workspace.fs` API: `readFile`, `writeFile`, `mkdir`, `grep`, etc. |
| [05. Runtime Interface](./05_runtime_interface.md) | Stable | `Workspace.runtime.exec/getExec/killExec/disposeExec` and backend routing. |
| [06. Mount Interface](./06_mount_interface.md) | Stable | Pre-filling paths from R2, Artifacts, GitHub, and custom sources. **(not yet implemented)** |
| [07. Injected Service](./07_injected_service.md) | Experimental | The in-container `computerd` service that backs FUSE and shell. |
| [08. Capnweb Interface](./08_capnweb_interface.md) | Experimental | RPC wire protocol between the DO and the sandbox. |
| [09. Tool Interface (Agents)](./09_tool_interface.md) | Stable | Ready-made AI SDK tools for `@cloudflare/agents`. |
| [10. Project Layout](./10_project_layout.md) | Reference | Source tree of this package and how the pieces fit together. |
| [11. Lifecycle](./11_lifecycle.md) | Mixed: stub disposal is stable; the container and capnweb lifecycle are experimental | DO incarnations, container lifetime, capnweb session lifecycle, and hibernation. |
| [12. Worker backend](./12_worker_backend.md) | Experimental | Running the shell as just-bash inside a Dynamic Worker loaded through `env.LOADER`. |
| [13. Git interface](./13_git_interface.md) | Stable | `workspace.git` and the `git` CLI inside the shell, backed by isomorphic-git. |
| [14. Assets interface](./14_assets_interface.md) | Stable | `share` a workspace file to R2 and get back a presigned URL. |
| [15. Artifacts interface](./15_artifacts_interface.md) | Stable | `createArtifact` and the `artifacts` CLI, an optionally session-scoped wrapper over the Cloudflare Artifacts binding. |
| [16. Execution runtime architecture](./16_code_execution.md) | Stable | One runtime entry point over command and module backends. |
| [17. Isolate JavaScript runtime](./17_isolate_javascript.md) | Stable, except `ws:container` | ECMAScript modules, durable imports, configured libraries, durable `node:fs/promises`, host modules, and managed lifecycle. |
| [18. Runtime migration](./18_runtime_migration.md) | Reference | Breaking preview-API mappings from public shell and script-execution surfaces to `workspace.runtime`. |
| [19. Performance](./19_performance.md) | Reference | Filesystem benchmarks: `fs-bench` numbers, an `npm install` comparison, and how to reproduce them. |

## High-level API

```ts
interface Workspace {
  fs: WorkspaceFilesystem;
  runtime: WorkspaceRuntime;

  /** Push pending DO-side writes to the configured backend. Resolves with the entry count. */
  push():  Promise<number>;
  /** Pull backend-side writes back into the DO. Resolves with { applied, skipped }. */
  pull():  Promise<ApplyResult>;
  /** Lazy-connect over the configured backends. Idempotent; safe to call from `onStart`. */
  ready(): Promise<void>;
  /** Wrap this Workspace in a stub for crossing the Workers RPC boundary. */
  stub():  WorkspaceStub;
  /** Tear down backend connections. */
  close(): Promise<void>;
}
```

See [04. Filesystem Interface](./04_filesystem_interface.md) and
[05. Runtime Interface](./05_runtime_interface.md) for the full surface, and [02. Sync Protocol](./02_sync_protocol.md) for `push`/`pull` semantics.

import { cloudflareTest } from "@cloudflare/vitest-pool-workers";
import { defineConfig } from "vitest/config";

export default defineConfig({
  plugins: [
    cloudflareTest({
      wrangler: { configPath: "./wrangler.test.jsonc" },
    }),
  ],
  test: {
    include: ["src/**/*.test.ts"],
  },
});

import type { Workspace } from "@cloudflare/computer";
import { describe, expect, it, vi } from "vitest";
import { seedWorkspace } from "./agent-common";
import type { OolongRealFixture } from "./benchmark";

describe("seedWorkspace", () => {
  it("clears stale fixture files before writing a new sample", async () => {
    const calls: string[] = [];
    const workspace = {
      ready: vi.fn<() => Promise<number>>(async () => calls.push("ready")),
      fs: {
        rm: vi.fn<() => Promise<number>>(async () => calls.push("rm")),
        mkdir: vi.fn<() => Promise<number>>(async () => calls.push("mkdir")),
        writeFile: vi.fn<(path: string) => Promise<number>>(async (path: string) =>
          calls.push(`write:${path}`),
        ),
      },
    } as unknown as Workspace;
    const fixture = {
      context: "new context",
      chunks: ["new chunk"],
      manifest: {
        contextChunks: [{ path: "/workspace/oolong-real/context-0000.txt" }],
      },
    } as unknown as OolongRealFixture;

    await seedWorkspace(workspace, fixture);

    expect(workspace.fs.rm).toHaveBeenCalledWith("/workspace/oolong-real", {
      recursive: true,
      force: true,
    });
    expect(calls.slice(0, 3)).toEqual(["ready", "rm", "mkdir"]);
  });
});

import { describe, expect, test } from "vitest";
import { comparisonFixture } from "../shared/fixture";
import { runComparisonAgents } from "./comparison-agents";
import type { RunEventInput } from "./run-events";

describe("runComparisonAgents", () => {
  test("records runtime and run terminal events", async () => {
    const events: RunEventInput[] = [];

    await runComparisonAgents({
      runId: "run-abc",
      fixture: comparisonFixture,
      workspaceAgent: {
        async runComparison() {},
      },
      sandboxAgent: {
        async runComparison() {
          throw new Error("capacity exceeded");
        },
      },
      appendEvent(input) {
        events.push(input);
      },
    });

    expect(events).toEqual([
      {
        runtime: "workspace",
        kind: "runtime_started",
        title: "Workspace runtime started",
        detail: "Workspace Think agent is running.",
      },
      {
        runtime: "sandbox",
        kind: "runtime_started",
        title: "Sandbox runtime started",
        detail: "Sandbox Think agent is running.",
      },
      {
        runtime: "workspace",
        kind: "runtime_completed",
        title: "Workspace runtime completed",
        detail: "Workspace Think agent completed.",
      },
      {
        runtime: "sandbox",
        kind: "runtime_failed",
        title: "Sandbox runtime failed",
        detail: "capacity exceeded",
      },
      {
        runtime: "both",
        kind: "run_completed",
        title: "Comparison run complete",
        detail: "Workspace completed; Sandbox failed.",
      },
    ]);
  });
});

import { describe, expect, test, vi } from "vitest";

vi.mock("agents", () => ({
  getAgentByName: vi.fn<(...args: unknown[]) => unknown>(),
}));

import { getRuntimeAgentHandles } from "./runtime-agent-handles";

describe("getRuntimeAgentHandles", () => {
  test("requests Workspace and Sandbox agent handles concurrently", async () => {
    const calls: string[] = [];
    const workspace = deferred<unknown>();
    const sandbox = deferred<unknown>();

    const handles = getRuntimeAgentHandles({
      runId: "run-abc",
      workspaceNamespace: {} as DurableObjectNamespace,
      sandboxNamespace: {} as DurableObjectNamespace,
      getAgent(_namespace, name) {
        calls.push(`start ${name}`);
        if (name.endsWith("-workspace")) return workspace.promise;
        if (name.endsWith("-sandbox")) return sandbox.promise;
        throw new Error(`unexpected agent ${name}`);
      },
    });

    await flushPromises();
    expect(calls).toEqual(["start run-abc-workspace", "start run-abc-sandbox"]);

    workspace.resolve({ runComparison: async () => {} });
    sandbox.resolve({ runComparison: async () => {} });
    await expect(handles.workspaceAgent).resolves.toEqual({ runComparison: expect.any(Function) });
    await expect(handles.sandboxAgent).resolves.toEqual({ runComparison: expect.any(Function) });
  });
});

async function flushPromises(): Promise<void> {
  await Promise.resolve();
  await Promise.resolve();
}

function deferred<T>() {
  let resolve!: (value: T | PromiseLike<T>) => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<T>((promiseResolve, promiseReject) => {
    resolve = promiseResolve;
    reject = promiseReject;
  });
  return { promise, resolve, reject };
}

import { beforeEach, describe, expect, it, vi } from "vitest";

import { createModel, type ModelEnv } from "./model";

const { createWorkersAIMock, selectModelMock } = vi.hoisted(() => ({
  createWorkersAIMock: vi.fn<(...args: unknown[]) => unknown>(),
  selectModelMock: vi.fn<(...args: unknown[]) => { specificationVersion: string }>(() => ({
    specificationVersion: "v3",
  })),
}));

vi.mock("workers-ai-provider", () => ({ createWorkersAI: createWorkersAIMock }));

beforeEach(() => {
  createWorkersAIMock.mockReset();
  selectModelMock.mockClear();
  createWorkersAIMock.mockReturnValue(selectModelMock);
});

describe("Workers AI transport selection", () => {
  it("prefers the authenticated AI binding even when REST credentials exist", () => {
    const binding = {} as Ai;
    createModel({
      AI: binding,
      CLOUDFLARE_ACCOUNT_ID: "account",
      CLOUDFLARE_API_TOKEN: "token",
    } as ModelEnv);

    expect(createWorkersAIMock).toHaveBeenCalledWith({ binding });
  });

  it("uses REST credentials only when the fallback is explicitly enabled", () => {
    createModel({
      AI: {} as Ai,
      CLOUDFLARE_ACCOUNT_ID: "account",
      CLOUDFLARE_API_TOKEN: "token",
      WORKERS_AI_USE_REST: "true",
    } as ModelEnv);

    expect(createWorkersAIMock).toHaveBeenCalledWith({ accountId: "account", apiKey: "token" });
  });
});

import { describe, expect, test } from "vitest";
import type { EventRuntime, RunEvent, RunEventKind } from "../shared/events";
import { buildDashboardModel } from "./dashboard-model";

describe("buildDashboardModel", () => {
  test("derives idle telemetry before a run starts", () => {
    const model = buildDashboardModel([], null);

    expect(model.run.status).toBe("idle");
    expect(model.run.actionLabel).toBe("START RUN");
    expect(model.runtimes.workspace.container).toBe("asleep");
    expect(model.runtimes.sandbox.container).toBe("off");
    expect(model.runtimes.workspace.toolCalls).toBe(0);
    expect(model.runtimes.sandbox.execCalls).toBe(0);
  });

  test("shows Sandbox cold boot while Workspace is already active", () => {
    const model = buildDashboardModel(
      [
        event({
          sequence: 0,
          runtime: "both",
          kind: "run_started",
          timestamp: "2026-06-04T00:00:00.000Z",
        }),
        event({
          sequence: 1,
          runtime: "workspace",
          kind: "runtime_started",
          timestamp: "2026-06-04T00:00:01.000Z",
        }),
        event({
          sequence: 2,
          runtime: "workspace",
          kind: "tool_call",
          title: "read called",
          detail: JSON.stringify({ name: "read", path: "/workspace/repo/src/index.ts" }),
          timestamp: "2026-06-04T00:00:02.000Z",
        }),
        event({
          sequence: 3,
          runtime: "sandbox",
          kind: "runtime_started",
          timestamp: "2026-06-04T00:00:03.000Z",
        }),
      ],
      "2026-06-04T00:00:04.000Z",
    );

