import { type ToolSet, tool } from "ai";
import { describe, expect, it } from "vitest";
import { z } from "zod";

import { SQLiteTestStorage } from "@cloudflare/dofs/testing";

import type { WorkspaceModuleCallContext } from "../../runtime/types.js";
import { Workspace } from "../../workspace.js";
import { forAISDKTools } from "./bindings.js";
import { createAITools } from "./index.js";

function callContext(): WorkspaceModuleCallContext {
  return {
    signal: new AbortController().signal,
    deadline: Date.now() + 60_000,
    access: "read-write",
    resolvePath: async (path) => path,
  };
}

function bindingFor(source: ReturnType<typeof forAISDKTools>, name: string) {
  const binding = [...source()].find((candidate) => candidate.name === name);
  if (!binding) throw new Error(`no ${name} binding`);
  return binding;
}

describe("forAISDKTools", () => {
  it("runs a tool with the code's arguments, a call id, and the call's signal", async () => {
    const seen: unknown[] = [];
    const tools = {
      weather: tool({
        description: "Weather for a city.",
        inputSchema: z.object({ city: z.string() }),
        execute: async (input, options) => {
          seen.push({ input, toolCallId: options.toolCallId, signal: options.abortSignal });
          return { forecast: "sunny" };
        },
      }),
    };
    const context = callContext();

    const result = await bindingFor(forAISDKTools(tools), "weather").call(
      { city: "Lisbon" },
      context,
    );

    expect(seen).toEqual([
      {
        input: { city: "Lisbon" },
        toolCallId: expect.stringMatching(/^ws-tools-/),
        signal: context.signal,
      },
    ]);
    expect(result).toEqual({
      text: '{"forecast":"sunny"}',
      details: { forecast: "sunny" },
      isError: false,
    });
  });

  it("returns a string result as text, and the last value of a streaming tool", async () => {
    const tools = {
      echo: tool({
        inputSchema: z.object({ value: z.string() }),
        execute: async ({ value }) => value,
      }),
      count: tool({
        inputSchema: z.object({}),
        async *execute() {
          yield "one";
          yield "two";
        },
      }),
    };
    await expect(
      bindingFor(forAISDKTools(tools), "echo").call({ value: "hi" }, callContext()),
    ).resolves.toEqual({ text: "hi", details: "hi", isError: false });
    await expect(
      bindingFor(forAISDKTools(tools), "count").call({}, callContext()),
    ).resolves.toEqual({ text: "two", details: "two", isError: false });
  });

  it("checks the arguments against the tool's schema, and runs it with the parsed value", async () => {
    const seen: unknown[] = [];
    const tools = {
      grep: tool({
        inputSchema: z.object({ query: z.string(), path: z.string().default("/workspace") }),
        execute: async (input) => {
          seen.push(input);
          return "found";
        },
      }),
    };
    const binding = bindingFor(forAISDKTools(tools), "grep");

    await binding.call({ query: "TODO" }, callContext());
    expect(seen).toEqual([{ query: "TODO", path: "/workspace" }]);

    await expect(binding.call({ path: 3 }, callContext())).rejects.toThrow(
      /^Invalid arguments for grep: /,
    );
    expect(seen).toHaveLength(1);
  });

  it("reports a result shaped { error: string } as a failure", async () => {
    const tools = {
      read: tool({
        inputSchema: z.object({ path: z.string() }),
        execute: async ({ path }) => ({ error: `File not found: ${path}` }),
      }),
    };
    await expect(
      bindingFor(forAISDKTools(tools), "read").call({ path: "/missing" }, callContext()),
    ).resolves.toEqual({
      text: "File not found: /missing",
      details: { error: "File not found: /missing" },
      isError: true,
    });
  });

  it("reports a failed read from createAITools as a failure", async () => {
    const workspace = new Workspace({
      storage: new SQLiteTestStorage(),
      now: () => 1_700_000_000_000,
    });
    await workspace.fs.mkdir("/workspace", { recursive: true });
    const result = await bindingFor(forAISDKTools(createAITools({ workspace })), "read").call(
      { path: "/workspace/missing.txt" },
      callContext(),
    );
    expect(result.isError).toBe(true);
    expect(result.text).toContain("/workspace/missing.txt");
  });

  it("leaves out tools that cannot run on the server or need approval", () => {
    const tools = {
      clientOnly: tool({ inputSchema: z.object({}) }),
      launch: tool({
        inputSchema: z.object({}),
        needsApproval: true,
        execute: async () => "launched",
      }),
      ok: tool({ inputSchema: z.object({}), execute: async () => "ok" }),
    };
    expect([...forAISDKTools(tools)()].map((binding) => binding.name)).toEqual(["ok"]);
  });

  it("calls the tool the function returns at call time, not when bindings were taken", async () => {
    let answer = "first";
    const source = forAISDKTools(() => ({
      answer: tool({ inputSchema: z.object({}), execute: async () => answer }),
    }));
    const binding = bindingFor(source, "answer");
    answer = "second";
    await expect(binding.call({}, callContext())).resolves.toMatchObject({ text: "second" });
  });

  it("rejects the call when the tool is gone by the time code calls it", async () => {
    let tools: ToolSet = {
      gone: tool({ inputSchema: z.object({}), execute: async () => "here" }),
    };
    const binding = bindingFor(
      forAISDKTools(() => tools),
      "gone",
    );
    tools = {};
    await expect(binding.call({}, callContext())).rejects.toThrow('No tool named "gone"');
  });
});

import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { WorkspaceFilesystem } from "./fs/filesystem.js";
import { NodeSQLiteStorage } from "./node-storage.js";
import { initializeSchema, ROOT_INODE, SCHEMA_VERSION } from "./schema/index.js";
import { Database } from "./storage.js";
import {
  readFetchCursor,
  readPushCursor,
  writeFetchCursor,
  writePushCursor,
} from "./sync/watermarks.js";

let dir: string;

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), "dofs-node-storage-"));
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
});

function openStore(path: string): { storage: NodeSQLiteStorage; db: Database } {
  const storage = new NodeSQLiteStorage({ location: path });
  const db = new Database(storage);
  initializeSchema(db, () => 1000);
  return { storage, db };
}

describe("NodeSQLiteStorage on a file", () => {
  it("keeps files and their bytes across a close and reopen", async () => {
    const path = join(dir, "state.db");

    const first = openStore(path);
    const fs = new WorkspaceFilesystem(first.db, { now: () => 1000 });
    await fs.mkdir("/workspace/repo", { recursive: true });
    await fs.writeFile("/workspace/repo/a.txt", "hello from the first process");
    first.storage.close();

    const second = openStore(path);
    const reopened = new WorkspaceFilesystem(second.db, { now: () => 2000 });
    const contents = await reopened.readFile("/workspace/repo/a.txt", "utf8");
    second.storage.close();

    expect(contents).toBe("hello from the first process");
  });

  it("keeps the sync cursors across a close and reopen", () => {
    const path = join(dir, "state.db");

    const first = openStore(path);
    writePushCursor(first.db, { rev: 42, path: null });
    writeFetchCursor(first.db, { rev: 41, path: "/workspace/b.txt" });
    first.storage.close();

    const second = openStore(path);
    const push = readPushCursor(second.db);
    const fetch = readFetchCursor(second.db);
    second.storage.close();

    expect(push).toEqual({ rev: 42, path: null });
    expect(fetch).toEqual({ rev: 41, path: "/workspace/b.txt" });
  });

  it("does not re-seed the root inode when reopening an existing store", () => {
    const path = join(dir, "state.db");

    const first = openStore(path);
    first.db.run("UPDATE vfs_nodes SET mtime = ? WHERE inode = ?", 5555, ROOT_INODE);
    first.storage.close();

    const second = openStore(path);
    const mtime = second.db.scalar<number>(
      "SELECT mtime FROM vfs_nodes WHERE inode = ?",
      ROOT_INODE,
    );
    const version = second.db.scalar<number>(
      "SELECT v FROM vfs_meta WHERE k = ?",
      "schema_version",
    );
    second.storage.close();

    expect(mtime).toBe(5555);
    expect(version).toBe(SCHEMA_VERSION);
  });

  it("turns on write-ahead logging", () => {
    const path = join(dir, "state.db");
    const { storage, db } = openStore(path);

    const mode = db.scalar<string>("PRAGMA journal_mode");
    storage.close();

    expect(mode).toBe("wal");
  });

  it("converts a byte cache budget into SQLite's negative kibibyte form", () => {
    const path = join(dir, "state.db");
    const storage = new NodeSQLiteStorage({
      location: path,
      cacheSizeBytes: 64 * 1024 * 1024,
    });
    const db = new Database(storage);

    const cacheSize = db.scalar<number>("PRAGMA cache_size");
    storage.close();

    expect(cacheSize).toBe(-65536);
  });

  it("applies the memory map size it was given", () => {
    const path = join(dir, "state.db");
    const storage = new NodeSQLiteStorage({
      location: path,
      mmapSizeBytes: 256 * 1024 * 1024,
    });
    const db = new Database(storage);

    const mmapSize = db.scalar<number>("PRAGMA mmap_size");
    storage.close();

    expect(mmapSize).toBe(268435456);
  });

  it("applies the synchronous level it was given", () => {
    const path = join(dir, "state.db");
    const storage = new NodeSQLiteStorage({ location: path, synchronous: "normal" });
    const db = new Database(storage);

    const level = db.scalar<number>("PRAGMA synchronous");
    storage.close();

    expect(level).toBe(1);
  });

  it("keeps temporary tables in memory", () => {
    const path = join(dir, "state.db");
    const { storage, db } = openStore(path);

    const tempStore = db.scalar<number>("PRAGMA temp_store");
    storage.close();

    expect(tempStore).toBe(2);
  });

  it("creates the database file when it does not exist", async () => {
    const path = join(dir, "nested", "state.db");
    const { storage, db } = openStore(path);
    const fs = new WorkspaceFilesystem(db, { now: () => 1000 });

    await fs.writeFile("/probe.txt", "x");
    storage.close();

    const reopened = openStore(path);
    const contents = await new WorkspaceFilesystem(reopened.db).readFile("/probe.txt", "utf8");
    reopened.storage.close();

    expect(contents).toBe("x");
  });

  it("leaves the store readable after a checkpoint", async () => {
    const path = join(dir, "state.db");
    const { storage, db } = openStore(path);
    const fs = new WorkspaceFilesystem(db, { now: () => 1000 });
    await fs.writeFile("/checkpointed.txt", "still here");

    storage.checkpoint();

    const contents = await fs.readFile("/checkpointed.txt", "utf8");
    storage.close();

    expect(contents).toBe("still here");
  });

  it("reports the bytes a checkpoint folded back into the main file", async () => {
    const path = join(dir, "state.db");
    const { storage, db } = openStore(path);
    const fs = new WorkspaceFilesystem(db, { now: () => 1000 });
    await fs.writeFile("/sized.txt", "x".repeat(4096));

    const result = storage.checkpoint();
    storage.close();

    expect(result.sizeBytes).toBeGreaterThan(0);
  });

  it("rolls back a failed transaction", () => {
    const path = join(dir, "state.db");
    const { storage, db } = openStore(path);

    expect(() => {
      db.transactionSync(() => {
        db.run("INSERT INTO vfs_meta (k, v) VALUES (?, ?)", "rollback_probe", 1);
        throw new Error("forced");
      });
    }).toThrow("forced");

    const value = db.scalar<number>("SELECT v FROM vfs_meta WHERE k = ?", "rollback_probe");
    storage.close();

    expect(value).toBeUndefined();
  });

  it("commits an inner savepoint while the outer transaction continues", () => {
    const path = join(dir, "state.db");
    const { storage, db } = openStore(path);

    db.transactionSync(() => {
      db.run("INSERT INTO vfs_meta (k, v) VALUES (?, ?)", "outer", 1);
      db.transactionSync(() => {
        db.run("INSERT INTO vfs_meta (k, v) VALUES (?, ?)", "inner", 2);
      });
    });

    const outer = db.scalar<number>("SELECT v FROM vfs_meta WHERE k = ?", "outer");
    const inner = db.scalar<number>("SELECT v FROM vfs_meta WHERE k = ?", "inner");
    storage.close();

    expect(outer).toBe(1);
    expect(inner).toBe(2);
  });

  it("rolls the outer transaction back over a committed inner savepoint", () => {
    const path = join(dir, "state.db");
    const { storage, db } = openStore(path);

    expect(() => {
      db.transactionSync(() => {
        db.transactionSync(() => {
          db.run("INSERT INTO vfs_meta (k, v) VALUES (?, ?)", "nested_probe", 1);
        });
        throw new Error("forced");
      });
    }).toThrow("forced");

    const value = db.scalar<number>("SELECT v FROM vfs_meta WHERE k = ?", "nested_probe");
    storage.close();

    expect(value).toBeUndefined();
  });
});

describe("NodeSQLiteStorage in memory", () => {
  it("accepts the in-memory location and serves a working schema", () => {
    const storage = new NodeSQLiteStorage({ location: ":memory:" });
    const db = new Database(storage);
    initializeSchema(db, () => 1234);

    const row = db.one<{ inode: number; type: string }>(
      "SELECT inode, type FROM vfs_nodes WHERE inode = ?",
      ROOT_INODE,
    );
    storage.close();

    expect(row).toEqual({ inode: ROOT_INODE, type: "dir" });
  });

  it("leaves journal mode alone for an in-memory store", () => {
    const storage = new NodeSQLiteStorage({ location: ":memory:" });
    const db = new Database(storage);

    const mode = db.scalar<string>("PRAGMA journal_mode");
    storage.close();

    expect(mode).toBe("memory");
  });

  it("reports nothing to fold when checkpointing an in-memory store", () => {
    const storage = new NodeSQLiteStorage({ location: ":memory:" });
    new Database(storage);

    const result = storage.checkpoint();
    storage.close();

    expect(result.walFrames).toBe(0);
  });
});

import { describe, expect, it, vi } from "vitest";
import { clearBlobCache, getBlobBytes } from "./blobCache.js";
import { readRangeSync } from "./readFile.js";
import { withDB } from "./with-db.js";
import { CHUNK_SIZE, writeFileSync } from "./writeFile.js";

describe("blobCache", () => {
  it("reuses bytes for the same hash across calls", async () => {
    await withDB(async (db) => {
      writeFileSync(db, "/seed.bin", new Uint8Array(CHUNK_SIZE).fill(7), {}, () => 1);
      // Pull the chunk hash out of vfs_chunks so we can hit the
      // cache helper directly without going through readFile.
      const row = db.one<{ hash: Uint8Array }>(
        "SELECT hash FROM vfs_chunks WHERE inode = (SELECT child_inode FROM vfs_dirents WHERE name = ?)",
        "seed.bin",
      );
      expect(row).toBeDefined();
      const hash = row?.hash as Uint8Array;

      // First call populates the cache; the second returns the
      // exact same Uint8Array reference rather than re-querying.
      const first = getBlobBytes(db, hash);
      expect(first).toBeInstanceOf(Uint8Array);
      const second = getBlobBytes(db, hash);
      expect(second).toBe(first);
    });
  });

  it("evicts the least-recently-used entry once 17 distinct hashes are cached", async () => {
    await withDB(async (db) => {
      // Stage 17 files with distinct content so each one gets a
      // unique blob hash. The cache holds 16; the 17th fetch must
      // evict the least-recently-used, which is the first hash.
      const hashes: Uint8Array[] = [];
      for (let i = 0; i < 17; i++) {
        const path = `/distinct-${i}.bin`;
        writeFileSync(db, path, new TextEncoder().encode(`payload-${i}`), {}, () => 1);
        const row = db.one<{ hash: Uint8Array }>(
          "SELECT hash FROM vfs_chunks WHERE inode = (SELECT child_inode FROM vfs_dirents WHERE name = ?)",
          `distinct-${i}.bin`,
        );
        hashes.push(row?.hash as Uint8Array);
      }
      clearBlobCache(db);

      // First 16 fetches populate the cache.
      for (let i = 0; i < 16; i++) getBlobBytes(db, hashes[i]);
      // 17th fetch evicts the LRU (entry 0); spy to confirm the
      // 18th fetch of hash 0 is a fresh SQL lookup, but hash 16 is
      // cached and the 18th fetch of hash 1 (still the LRU) hits
      // SQL too.
      getBlobBytes(db, hashes[16]);

      const spy = vi.spyOn(db, "one");
      getBlobBytes(db, hashes[0]); // evicted, must hit SQL
      getBlobBytes(db, hashes[16]); // hot, must NOT hit SQL
      const lookups = spy.mock.calls.filter(
        ([query]) => typeof query === "string" && query.includes("vfs_blob_bytes"),
      ).length;
      spy.mockRestore();

      expect(lookups).toBe(1);
    });
  });

  it("moves a touched entry to most-recent so it survives eviction", async () => {
    await withDB(async (db) => {
      const hashes: Uint8Array[] = [];
      for (let i = 0; i < 17; i++) {
        const path = `/touched-${i}.bin`;
        writeFileSync(db, path, new TextEncoder().encode(`touched-${i}`), {}, () => 1);
        const row = db.one<{ hash: Uint8Array }>(
          "SELECT hash FROM vfs_chunks WHERE inode = (SELECT child_inode FROM vfs_dirents WHERE name = ?)",
          `touched-${i}.bin`,
        );
        hashes.push(row?.hash as Uint8Array);
      }
      clearBlobCache(db);

      for (let i = 0; i < 16; i++) getBlobBytes(db, hashes[i]);
      // Touch hash 0 so it becomes most-recent.
      getBlobBytes(db, hashes[0]);
      // The 17th fetch should now evict hash 1, not hash 0.
      getBlobBytes(db, hashes[16]);

      const spy = vi.spyOn(db, "one");
      getBlobBytes(db, hashes[0]); // touched, still cached
      getBlobBytes(db, hashes[1]); // evicted, must hit SQL
      const lookups = spy.mock.calls.filter(
        ([query]) => typeof query === "string" && query.includes("vfs_blob_bytes"),
      ).length;
      spy.mockRestore();

      expect(lookups).toBe(1);
    });
  });

  it("readRangeSync avoids repeating vfs_blob_bytes lookups on sequential reads", async () => {
    await withDB(async (db) => {
      // 4 MiB of repeated content → one dedup'd blob in the store.
      // A sequential read in 128 KiB windows used to issue one
      // SELECT bytes per window, even though every window came out
      // of the same blob.
      const payload = new Uint8Array(CHUNK_SIZE * 8).fill(3);
      writeFileSync(db, "/big.bin", payload, {}, () => 1);
      clearBlobCache(db);

      const spy = vi.spyOn(db, "one");
      const window = 128 * 1024;
      for (let offset = 0; offset < payload.byteLength; offset += window) {
        readRangeSync(db, "/big.bin", offset, window);
      }
      const blobLookups = spy.mock.calls.filter(
        ([query]) => typeof query === "string" && query.includes("vfs_blob_bytes"),
      ).length;
      spy.mockRestore();

      // 8 distinct chunks were written and they all share one
      // hash; we should fetch the blob bytes at most once.
      expect(blobLookups).toBeLessThanOrEqual(1);
    });
  });
});

import { describe, expect, it } from "vitest";
import { applyChangesSync } from "../sync/apply.js";
import { link } from "./link.js";
import { mkdir } from "./mkdir.js";
import { rename } from "./rename.js";
import { resolveInode } from "./resolve.js";
import { invalidateResolveExact } from "./resolveCache.js";
import { rm } from "./rm.js";
import { symlink } from "./symlink.js";
import { withDB } from "./with-db.js";
import { writeFileSync } from "./writeFile.js";

const NOW = (): number => 1000;

function bytesOf(text: string): Uint8Array {
  return new TextEncoder().encode(text);
}

// These prove the path->inode cache never serves a stale result across
// every mutation shape, and that the recursive-CTE resolve's symlink
// fallback matches the per-component loop. They run under both backends
// (node:sqlite and real DO SqlStorage) via withDB, so cache correctness
// is exercised on the shipping storage.
describe("resolve cache + CTE resolve", () => {
  it("drops a negative entry the instant the path is created", async () => {
    await withDB(async (db) => {
      mkdir(db, "/d", { recursive: true }, NOW);
      // Prime a negative entry.
      expect(resolveInode(db, "/d/f")).toBeNull();
      writeFileSync(db, "/d/f", bytesOf("x"), {}, NOW);
      // Must resolve to the new inode, not a stale ENOENT.
      expect(resolveInode(db, "/d/f")?.type).toBe("file");
    });
  });

  it("invalidates a positive entry on unlink, rename, and rmdir", async () => {
    await withDB(async (db) => {
      mkdir(db, "/p", { recursive: true }, NOW);

      writeFileSync(db, "/p/a", bytesOf("a"), {}, NOW);
      expect(resolveInode(db, "/p/a")?.inode).toBeGreaterThan(0); // prime
      rm(db, "/p/a", {});
      expect(resolveInode(db, "/p/a")).toBeNull();

      writeFileSync(db, "/p/b", bytesOf("b"), {}, NOW);
      expect(resolveInode(db, "/p/b")).not.toBeNull(); // prime
      rename(db, "/p/b", "/p/c");
      expect(resolveInode(db, "/p/b")).toBeNull();
      expect(resolveInode(db, "/p/c")).not.toBeNull();

      mkdir(db, "/p/sub", { recursive: true }, NOW);
      expect(resolveInode(db, "/p/sub")).not.toBeNull(); // prime
      rm(db, "/p/sub", {});
      expect(resolveInode(db, "/p/sub")).toBeNull();
    });
  });

  it("invalidates every descendant path on a directory rename", async () => {
    await withDB(async (db) => {
      mkdir(db, "/src/inner", { recursive: true }, NOW);
      writeFileSync(db, "/src/inner/deep.txt", bytesOf("d"), {}, NOW);
      // Prime positives for the whole chain.
      const deepInode = resolveInode(db, "/src/inner/deep.txt")?.inode;
      expect(resolveInode(db, "/src/inner")).not.toBeNull();
      expect(deepInode).toBeGreaterThan(0);

      rename(db, "/src", "/dst");

      // Old descendant paths must be gone, not stale positives.
      expect(resolveInode(db, "/src/inner/deep.txt")).toBeNull();
      expect(resolveInode(db, "/src/inner")).toBeNull();
      expect(resolveInode(db, "/src")).toBeNull();
      // New paths resolve; the moved file keeps its inode.
      expect(resolveInode(db, "/dst/inner/deep.txt")?.inode).toBe(deepInode);
    });
  });

  it("resolves a hardlink's second name to the shared inode", async () => {
    await withDB(async (db) => {
      mkdir(db, "/h", { recursive: true }, NOW);
      writeFileSync(db, "/h/a", bytesOf("shared"), {}, NOW);
      const inode = resolveInode(db, "/h/a")?.inode;
      // Prime a negative for the not-yet-existing link path.
      expect(resolveInode(db, "/h/b")).toBeNull();
      link(db, "/h/a", "/h/b");
      expect(resolveInode(db, "/h/b")?.inode).toBe(inode);
    });
  });

  it("reflects a sync-applied change through cached negative and positive paths", async () => {
    await withDB(async (db) => {
      mkdir(db, "/s", { recursive: true }, NOW);
      writeFileSync(db, "/s/existing", bytesOf("e"), {}, NOW);
      // Prime: negative for a dir we will create, positive for a file we
      // will delete.
      expect(resolveInode(db, "/s/newdir")).toBeNull();
      expect(resolveInode(db, "/s/existing")).not.toBeNull();

      // applyChangesSync funnels through mkdir (create) and rm (delete),
      // both of which invalidate the cache.
      applyChangesSync(
        db,
        [
          { kind: "dir", rev: 1, path: "/s/newdir", mode: 0o755, mtime: 1000 },
          { kind: "delete", rev: 2, path: "/s/existing" },
        ],
        new Map(),
      );

      expect(resolveInode(db, "/s/newdir")?.type).toBe("dir");
      expect(resolveInode(db, "/s/existing")).toBeNull();

      // Apply a symlink over a POPULATED directory: exercises apply's own
      // conflict-cleanup branch (removeReplaceableFinalEntry ->
      // removeInodeTreeAtPath subtree invalidation) plus symlink-create
      // invalidation, with a primed descendant positive.
      mkdir(db, "/s/dir/child", { recursive: true }, NOW);
      expect(resolveInode(db, "/s/dir/child")).not.toBeNull();
      expect(resolveInode(db, "/s/dir")?.type).toBe("dir");
      applyChangesSync(
        db,
        [
          {
            kind: "symlink",
            rev: 3,
            path: "/s/dir",
            target: "/elsewhere",
            mode: 0o777,
            mtime: 1000,
          },
        ],
        new Map(),
      );
      // /s/dir is now a symlink; the former descendant no longer resolves.
      expect(resolveInode(db, "/s/dir", { followSymlinks: false })?.type).toBe("symlink");
      expect(resolveInode(db, "/s/dir/child")).toBeNull();
    });
  });

  it("leaves no stale entry after a rolled-back write", async () => {
    await withDB(async (db) => {
      mkdir(db, "/r", { recursive: true }, NOW);
      const rDir = resolveInode(db, "/r")?.inode ?? 0;
      writeFileSync(db, "/r/keep", bytesOf("k"), {}, NOW);
      const keepInode = resolveInode(db, "/r/keep")?.inode; // prime positive
      expect(keepInode).toBeGreaterThan(0);

      // A mutation is (structural write + cache invalidation) inside one
      // transaction. This drives that shape with raw statements at a
      // single transaction level — the DO backend forbids the nested
      // savepoints an outer db.transactionSync around an fs op would use,
      // and the cache's rollback-safety is backend-independent anyway.

      // Rolled-back delete: the invalidation drops the entry mid-txn; the
      // rollback restores the dirent; the recompute finds it alive again
      // (no stale ENOENT).
      expect(() =>
        db.transactionSync(() => {
          db.run("DELETE FROM vfs_dirents WHERE parent_inode = ? AND name = ?", rDir, "keep");
          invalidateResolveExact(db, "/r/keep");
          throw new Error("boom-delete");
        }),
      ).toThrow("boom-delete");
      expect(resolveInode(db, "/r/keep")?.inode).toBe(keepInode);

      // Rolled-back create + inode reuse: population is gated inside a
      // transaction, so the doomed inode is never cached for /r/new. A
      // broken gate would cache it and, after AUTOINCREMENT reuses the
      // number on the next committed create, alias /r/new to /r/other.
      expect(resolveInode(db, "/r/new")).toBeNull(); // prime negative
      expect(() =>
        db.transactionSync(() => {
          db.run("INSERT INTO vfs_nodes (type, mode, mtime, rev) VALUES ('file', 420, 0, 0)");
          const inode = db.scalar<number>("SELECT last_insert_rowid() AS v") ?? 0;
          db.run(
            "INSERT INTO vfs_dirents (parent_inode, name, child_inode) VALUES (?, ?, ?)",
            rDir,
            "new",
            inode,
          );
          invalidateResolveExact(db, "/r/new");
          // Reading inside the txn must not populate the cache (the gate).
          expect(resolveInode(db, "/r/new")).not.toBeNull();
          throw new Error("boom-create");
        }),
      ).toThrow("boom-create");
      writeFileSync(db, "/r/other", bytesOf("o"), {}, NOW);
      expect(resolveInode(db, "/r/new")).toBeNull();
      expect(resolveInode(db, "/r/other")).not.toBeNull();
    });
  });

  it("falls back to the loop for symlinks, resolving identically", async () => {
    await withDB(async (db) => {
      mkdir(db, "/target/sub", { recursive: true }, NOW);
      writeFileSync(db, "/target/sub/file.txt", bytesOf("hello"), {}, NOW);
      const realInode = resolveInode(db, "/target/sub/file.txt")?.inode;

      // Intermediate symlink: /link -> /target.
      symlink(db, "/target", "/link", NOW);
      // Following through the link reaches the real file inode.
      expect(resolveInode(db, "/link/sub/file.txt")?.inode).toBe(realInode);
      // Following the link itself lands on the directory it points at.
      expect(resolveInode(db, "/link")?.type).toBe("dir");
      // lstat (no follow) lands on the symlink node itself.
      const withoutFollow = resolveInode(db, "/link", { followSymlinks: false });
      expect(withoutFollow?.type).toBe("symlink");
      expect(withoutFollow?.linkTarget).toBe("/target");

      // Dangling symlink: ENOENT when followed, symlink node when not.
      symlink(db, "/nope", "/dangling", NOW);
      expect(resolveInode(db, "/dangling")).toBeNull();
      expect(resolveInode(db, "/dangling", { followSymlinks: false })?.type).toBe("symlink");
    });
  });

  it("drops a negative primed beneath a path that a new symlink makes resolvable", async () => {
    await withDB(async (db) => {
      mkdir(db, "/target", { recursive: true }, NOW);
      writeFileSync(db, "/target/x", bytesOf("x"), {}, NOW);
      const realInode = resolveInode(db, "/target/x")?.inode;
      // Prime a negative for a path beneath where the link will land
      // (no symlink on the path yet, so the negative is cached).
      expect(resolveInode(db, "/link/x")).toBeNull();

      // Creating the symlink makes "/link/x" resolvable through it; the
      // subtree invalidation must drop the stale negative beneath it.
      symlink(db, "/target", "/link", NOW);
      expect(resolveInode(db, "/link/x")?.inode).toBe(realInode);
    });
  });

  it("does not cache a negative when a symlink on the path forces the loop", async () => {
    await withDB(async (db) => {
      mkdir(db, "/target", { recursive: true }, NOW);
      symlink(db, "/target", "/link", NOW);
      // Resolve through the link before the leaf exists: the CTE bails
      // to the loop and must cache nothing for the aliased path.
      expect(resolveInode(db, "/link/x")).toBeNull();

      // Create the real leaf. This invalidates "/target/x", not the
      // "/link/x" alias — so a negative wrongly cached by the bail would
      // linger and this read would still see null.
      writeFileSync(db, "/target/x", bytesOf("x"), {}, NOW);
      expect(resolveInode(db, "/link/x")?.type).toBe("file");
    });
  });
});

